diff --git a/broker/recovery/rotate_atomic_test.go b/broker/recovery/rotate_atomic_test.go
new file mode 100644
index 000000000..f2e4bb5bd
--- /dev/null
+++ b/broker/recovery/rotate_atomic_test.go
@@ -0,0 +1,134 @@
+package recovery
+
+import (
+	"bytes"
+	"errors"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/vault"
+)
+
+// REQ: CRED-7
+
+// ROTATE-card-atomic (#1440): the card's Wi-Fi password and setup secret
+// are their own vault entries so the redactor, which matches whole values,
+// covers them in agent-bound output. Storing a card must change the card
+// and those entries together. A save failing or the box crashing at any
+// save boundary of setup or a rotation leaves the vault, in memory and as
+// reopened from the drive, with entries matching the card it holds.
+
+// failingCounter is a PC counter whose Read fails from the armed call on:
+// a bound vault reads its counter at the start of every save, so the save
+// at that boundary fails before it writes anything.
+type failingCounter struct {
+	*pcCounter
+	reads, failAt int
+}
+
+var errCounterGone = errors.New("tpm: not answering")
+
+func (f *failingCounter) Read(ref, auth []byte) (uint64, error) {
+	f.reads++
+	if f.failAt > 0 && f.reads >= f.failAt {
+		return 0, errCounterGone
+	}
+	return f.pcCounter.Read(ref, auth)
+}
+
+// cardCovered checks that v holds a card whose Wi-Fi password and setup
+// secret are each a whole entry value, so the redactor covers them.
+func cardCovered(t *testing.T, v *vault.Vault, at string) Card {
+	t.Helper()
+	c, err := (&Box{V: v}).LoadCard()
+	if err != nil {
+		t.Fatalf("%s: %v", at, err)
+	}
+	r, err := v.Redactor()
+	if err != nil {
+		t.Fatalf("%s: %v", at, err)
+	}
+	for name, s := range map[string]string{"wifi": c.WiFiPassword, "setup": c.SetupSecret} {
+		out := r.Redact([]byte("the card says " + s + "."))
+		if bytes.Contains(out, []byte(s)) {
+			t.Fatalf("%s: card %s secret not redacted", at, name)
+		}
+	}
+	return c
+}
+
+func TestRotationCardStaysRedactedAtEverySaveBoundary(t *testing.T) {
+	parts := []Part{PartWiFi, PartSetup}
+	for n := 1; ; n++ {
+		if n > 50 {
+			t.Fatal("rotation never finished")
+		}
+		x := newBox(t)
+		fc := &failingCounter{pcCounter: newPCCounter("host-a")}
+		must(t, x.b.V.Anchor(fc))
+		before := cardCovered(t, x.b.V, "before")
+		p, err := BeginRotate(x.b, parts, Auth{Code: true, Local: true}, Proof{}, t0)
+		must(t, err)
+		next := newParts(p)
+		fc.failAt = fc.reads + n
+		_, err = p.Commit(x.b, next, t0)
+		fc.failAt = 0
+		got := cardCovered(t, x.b.V, "in memory")
+		x.b.V.Close()
+		v, oerr := vault.OpenSealed(x.b.VaultPath, x.b.KeysPath, Factor(x.rk))
+		must(t, oerr)
+		onDrive := cardCovered(t, v, "reopened")
+		v.Close()
+		if err == nil {
+			if got.WiFiPassword != next.WiFiPassword || got.SetupSecret != next.SetupSecret {
+				t.Fatal("rotation finished without the new card")
+			}
+			if n == 1 {
+				t.Fatal("no save boundary was tested")
+			}
+			return
+		}
+		if !errors.Is(err, errCounterGone) {
+			t.Fatalf("save %d: %v", n, err)
+		}
+		// Wi-Fi and setup rotate without a slot write, so a failed
+		// rotation keeps the old card whole.
+		for _, c := range []Card{got, onDrive} {
+			if c.WiFiPassword != before.WiFiPassword || c.SetupSecret != before.SetupSecret {
+				t.Fatalf("save %d: card changed by a failed rotation", n)
+			}
+		}
+	}
+}
+
+// Setup stores the first card the same way: a save failing at any
+// boundary leaves no card part, or the whole card.
+func TestProvisionCardStaysRedactedAtEverySaveBoundary(t *testing.T) {
+	for n := 1; ; n++ {
+		if n > 10 {
+			t.Fatal("store never finished")
+		}
+		x := newBox(t)
+		fc := &failingCounter{pcCounter: newPCCounter("host-a")}
+		must(t, x.b.V.Anchor(fc))
+		for _, e := range x.b.V.List() {
+			if e.Kind == KindCard || e.Kind == KindCardPart {
+				must(t, x.b.V.Delete(e.Name))
+			}
+		}
+		fc.failAt = fc.reads + n
+		err := storeCard(x.b, x.card)
+		fc.failAt = 0
+		if err == nil {
+			cardCovered(t, x.b.V, "stored")
+			return
+		}
+		if !errors.Is(err, errCounterGone) {
+			t.Fatalf("save %d: %v", n, err)
+		}
+		for _, e := range x.b.V.List() {
+			if e.Kind == KindCard || e.Kind == KindCardPart {
+				t.Fatalf("save %d: stray %s after a failed store", n, e.Name)
+			}
+		}
+	}
+}
diff --git a/broker/vault/putmany_test.go b/broker/vault/putmany_test.go
new file mode 100644
index 000000000..81784b0b3
--- /dev/null
+++ b/broker/vault/putmany_test.go
@@ -0,0 +1,165 @@
+package vault
+
+import (
+	"bytes"
+	"errors"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/durable"
+)
+
+// REQ: CRED-7
+
+// ROTATE-card-atomic (#1440): values that cover one another in redaction
+// are stored together. PutMany writes them in one save, so the vault, in
+// memory and on the drive, holds every old value or every new one, never
+// a mix.
+
+func putManyVault(t *testing.T) (*Vault, string, []byte) {
+	t.Helper()
+	path, key := filepath.Join(t.TempDir(), "vault"), testKey(t)
+	v, err := Create(path, key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { v.Close() })
+	return v, path, key
+}
+
+func items(t *testing.T, names ...string) ([]Item, map[string][]byte) {
+	t.Helper()
+	var its []Item
+	vals := map[string][]byte{}
+	for _, n := range names {
+		c := canary(t)
+		its = append(its, Item{Name: n, Kind: "card_part", Value: c})
+		vals[n] = c
+	}
+	return its, vals
+}
+
+// holds checks that v has exactly want's values under their names, and that
+// its redactor covers each of them.
+func holds(t *testing.T, v *Vault, want map[string][]byte) {
+	t.Helper()
+	r, err := v.Redactor()
+	if err != nil {
+		t.Fatal(err)
+	}
+	for n, val := range want {
+		s, ok := v.Secret(n)
+		if !ok || s.Reveal() != string(val) {
+			t.Fatalf("%s: not the expected value", n)
+		}
+		if bytes.Contains(r.Redact(append([]byte("out "), val...)), val) {
+			t.Fatalf("%s: value not redacted", n)
+		}
+	}
+}
+
+func TestPutManyWritesOnce(t *testing.T) {
+	v, path, key := putManyVault(t)
+	writes := 0
+	writeFile = func(p string, raw []byte, perm os.FileMode) error {
+		writes++
+		return durable.WriteFile(p, raw, perm)
+	}
+	t.Cleanup(func() { writeFile = durable.WriteFile })
+	its, vals := items(t, "card", "card-wifi", "card-setup")
+	if err := v.PutMany(its); err != nil {
+		t.Fatal(err)
+	}
+	if writes != 1 {
+		t.Fatalf("%d saves, want 1", writes)
+	}
+	holds(t, v, vals)
+	v2, err := Open(path, key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer v2.Close()
+	holds(t, v2, vals)
+}
+
+// A failed save puts every entry back, replaced and new alike, and the
+// drive keeps the file before.
+func TestPutManyFailedSaveRestoresAll(t *testing.T) {
+	v, path, key := putManyVault(t)
+	old, oldVals := items(t, "card", "card-wifi")
+	if err := v.PutMany(old); err != nil {
+		t.Fatal(err)
+	}
+	next, _ := items(t, "card", "card-wifi", "card-setup")
+	writeFile = func(string, []byte, os.FileMode) error { return errors.New("disk full") }
+	t.Cleanup(func() { writeFile = durable.WriteFile })
+	if err := v.PutMany(next); err == nil {
+		t.Fatal("no failure")
+	}
+	writeFile = durable.WriteFile
+	holds(t, v, oldVals)
+	if _, ok := v.Secret("card-setup"); ok {
+		t.Fatal("new entry kept after a failed save")
+	}
+	v2, err := Open(path, key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer v2.Close()
+	holds(t, v2, oldVals)
+	if len(v2.List()) != 2 {
+		t.Fatalf("on the drive: %v", v2.List())
+	}
+}
+
+// A save that fails after the new file landed (a failed directory sync)
+// leaves the drive with every new value: one file, one write.
+func TestPutManySaveFailsAfterRenameIsWhole(t *testing.T) {
+	v, path, key := putManyVault(t)
+	old, _ := items(t, "card", "card-wifi")
+	if err := v.PutMany(old); err != nil {
+		t.Fatal(err)
+	}
+	next, nextVals := items(t, "card", "card-wifi")
+	writeFile = func(p string, raw []byte, perm os.FileMode) error {
+		if err := durable.WriteFile(p, raw, perm); err != nil {
+			return err
+		}
+		return errors.New("dir sync failed")
+	}
+	t.Cleanup(func() { writeFile = durable.WriteFile })
+	if err := v.PutMany(next); err == nil {
+		t.Fatal("no failure")
+	}
+	writeFile = durable.WriteFile
+	v2, err := Open(path, key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer v2.Close()
+	holds(t, v2, nextVals)
+}
+
+// One bad item stores nothing.
+func TestPutManyRefusesBeforeWriting(t *testing.T) {
+	v, _, _ := putManyVault(t)
+	good, _ := items(t, "a", "b")
+	for name, bad := range map[string]Item{
+		"short":     {Name: "c", Kind: "k", Value: []byte("x")},
+		"no name":   {Kind: "k", Value: canary(t)},
+		"no kind":   {Name: "c", Value: canary(t)},
+		"duplicate": {Name: "a", Kind: "k", Value: canary(t)},
+	} {
+		if err := v.PutMany(append(append([]Item(nil), good...), bad)); err == nil {
+			t.Fatalf("%s: accepted", name)
+		}
+		if len(v.List()) != 0 {
+			t.Fatalf("%s: stored %v", name, v.List())
+		}
+	}
+	v.Close()
+	if err := v.PutMany(good); !errors.Is(err, ErrClosed) {
+		t.Fatalf("after Close: %v", err)
+	}
+}
